import json
async def main(args) -> dict:
    skills = args.params.get("skills") or []
    reason = args.params.get("reason") or ""
    if not skills:
        return {"suggest": "检测到可能是可复用任务，但暂无匹配技能。考虑用 save_skill 沉淀一个？"}
    lines = ["💡 检测到可能是可复用任务：" + reason]
    lines.append("相关技能建议：")
    for s in skills:
        lines.append(f"- `{s}`：可用 read_skill(\"{s}\") 查看 SOP")
    return {"suggest": "\n".join(lines)}
